<?php
// Uses an isolated SQLite in-memory connection. Never migrates or writes your MySQL database.
require __DIR__.'/../vendor/autoload.php';
$app = require __DIR__.'/../bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
config(['app.key'=>'native-center-smoke-test-only','database.default'=>'sqlite','database.connections.sqlite'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true], 'session.driver'=>'array','cache.default'=>'array','mail.default'=>'log']);
Illuminate\Support\Facades\DB::purge();
use Illuminate\Support\Facades\{DB,Schema};
use Illuminate\Database\Schema\Blueprint;
use Illuminate\Http\Request;
use App\Http\Controllers\MobileCenterController;
use App\Services\ApiToken;
$create=function($table,$columns){Schema::create($table,function(Blueprint $t)use($columns){$t->increments('id');foreach($columns as $column)$t->text($column)->nullable();});};
$create('users',['name','email','password','remember_token','role','courier_type','company_id','active','online','approval_status','account_status','verification_required','email_verified_at','last_seen_at','updated_at','phone','vehicle']);
$create('sorting_centers',['user_id','name','province','city','municipality_key']);
$create('notifications',['user_id','body','created_at','read_at']);
$create('registration_documents',['user_id','kind','path']);
$create('remittances',['company_id','rider_id','status','amount','expected','reference']);
$create('parcels',['status','center_id','destination_center_id','order_id']);
$create('assignments',['parcel_id','rider_id','kind','status','handed_over_at','handed_over_by']);
$create('driver_trip_items',['trip_id','parcel_id','stop_id']);
$create('driver_trips',['status']);
foreach([[1,'sorting_center',null,null],[2,'rider','rider',1],[3,'sorting_center',null,null],[4,'rider','rider',3]] as [$id,$role,$type,$company])DB::table('users')->insert(['id'=>$id,'name'=>'Account '.$id,'email'=>'u'.$id.'@example.test','password'=>password_hash('Test-password-123!',PASSWORD_BCRYPT),'role'=>$role,'courier_type'=>$type,'company_id'=>$company,'active'=>1,'online'=>1,'approval_status'=>'approved','account_status'=>'active','verification_required'=>0]);
DB::table('sorting_centers')->insert([['id'=>1,'user_id'=>1,'name'=>'Center One','province'=>'Laguna','city'=>'Calamba'],['id'=>2,'user_id'=>3,'name'=>'Center Two','province'=>'Laguna','city'=>'Santa Rosa']]);
DB::table('notifications')->insert([['user_id'=>1,'body'=>'Own notice'],['user_id'=>3,'body'=>'Other center secret']]);
DB::table('registration_documents')->insert(['id'=>20,'user_id'=>4,'kind'=>'id_document','path'=>'private/never-opened.pdf']);
DB::table('remittances')->insert(['id'=>20,'company_id'=>3,'rider_id'=>4,'status'=>'pending','amount'=>100,'expected'=>100]);
DB::table('parcels')->insert(['id'=>30,'status'=>'IN_TRANSIT_CENTER','center_id'=>2,'destination_center_id'=>1,'order_id'=>9]);
DB::table('assignments')->insert(['id'=>30,'parcel_id'=>30,'rider_id'=>4,'kind'=>'transfer','status'=>'accepted']);
$tokens=[];foreach([1,2,3,4] as $id)$tokens[$id]=ApiToken::issue(App\Models\User::find($id))[0];
$controller=new MobileCenterController();$checks=0;
$check=function($ok,$message)use(&$checks){if(!$ok)throw new RuntimeException($message);$checks++;};
$request=function($token,array $body=[]){$r=Request::create('/api/center/notifications','POST',$body,[],[],['HTTP_ACCEPT'=>'application/json','HTTP_AUTHORIZATION'=>'Bearer '.$token]);app()->instance('request',$r);return $r;};
$reject=function($fn,int $status)use($check){try{$fn();throw new RuntimeException('Request unexpectedly accepted');}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){$check($e->getStatusCode()===$status,'Unexpected denial status');}};
$reject(fn()=>$controller->index($request('bad-token'),'notifications'),401);
$reject(fn()=>$controller->index($request($tokens[2]),'notifications'),401);
$result=$controller->index($request($tokens[1]),'notifications')->getData(true);
$check(count($result['records'])===1 && $result['records'][0]['title']==='Own notice','Notification ownership');
$result=$controller->index($request($tokens[1]),'couriers')->getData(true);
$text=json_encode($result);
$check(str_contains($text,'Account 2')&&!str_contains($text,'Account 4'),'Courier list ownership');
$check(!str_contains($text,'password')&&!str_contains($text,'remember_token'),'No credential fields');
$reject(fn()=>$controller->index($request($tokens[1]),'arbitrary-controller'),404);
$reject(fn()=>$controller->mutate($request($tokens[1]),'arbitrary-method'),404);
$reject(fn()=>$controller->document($request($tokens[1]),20),403);
$reject(fn()=>$controller->mutate($request($tokens[1],['reason'=>'Checked the physical remittance']),'cod-confirm',20),403);
$check(DB::table('remittances')->where('id',20)->value('status')==='pending','Foreign remittance unchanged');
try{$controller->mutate($request($tokens[1],['confirm_receipt'=>true]),'transfer-receive',30);throw new RuntimeException('Receipt accepted before handover');}catch(Illuminate\Validation\ValidationException $e){$check(isset($e->errors()['handover']),'Driver handover is required');}
$check(DB::table('parcels')->where('id',30)->value('status')==='IN_TRANSIT_CENTER','Rejected receipt leaves parcel unchanged');
$controller->mutate($request($tokens[1]),'notifications-read');
$check(DB::table('notifications')->where('user_id',1)->whereNotNull('read_at')->count()===1,'Own notices marked read');
$check(DB::table('notifications')->where('user_id',3)->whereNull('read_at')->count()===1,'Other center notices untouched');
DB::table('users')->where('id',1)->update(['active'=>0]);
$reject(fn()=>$controller->index($request($tokens[1]),'notifications'),401);
echo "PASS: {$checks} isolated native center API checks.\n";
